1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Todos</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  body { margin: 0; padding: 2rem 1rem; font: 16px/1.4 system-ui, sans-serif; background: #f6f6f4; color: #222; }
10	  main { max-width: 32rem; margin: 0 auto; }
11	  h1 { margin: 0 0 1rem; font-size: 1.5rem; }
12	  form { display: flex; gap: .5rem; margin-bottom: 1rem; }
13	  input { flex: 1; padding: .5rem .75rem; font: inherit; border: 1px solid #ccc; border-radius: 6px; }
14	  button { padding: .5rem .9rem; font: inherit; border: 1px solid #bbb; border-radius: 6px; background: #fff; cursor: pointer; }
15	  button:hover { background: #eee; }
16	  ul { list-style: none; margin: 0; padding: 0; }
17	  li { display: flex; align-items: center; gap: .5rem; padding: .5rem .75rem; margin-bottom: .4rem; background: #fff; border: 1px solid #e2e2e2; border-radius: 6px; }
18	  li span { flex: 1; overflow-wrap: anywhere; }
19	  li[data-completed="true"] span { text-decoration: line-through; color: #888; }
20	  li input[type="checkbox"] { flex: none; width: 1.1rem; height: 1.1rem; margin: 0; }
21	  .filters { display: flex; gap: .5rem; margin-bottom: 1rem; }
22	  .filters button[aria-pressed="true"] { background: #222; border-color: #222; color: #fff; }
23	  form input[type="date"] { flex: none; }
24	  .due { flex: none; font-size: .85rem; color: #666; }
25	  li[data-overdue="true"] { border-color: #d33; background: #fff1f0; }
26	  li[data-overdue="true"] .due { color: #b00; font-weight: 600; }
27	</style>
28	</head>
29	<body>
30	<main>
31	  <h1>Todos</h1>
32	  <form id="todo-form">
33	    <input data-testid="todo-input" type="text" placeholder="What needs doing?" aria-label="New todo" autocomplete="off">
34	    <input data-testid="todo-due" type="date" aria-label="Due date (optional)">
35	    <button data-testid="todo-add" type="submit">Add</button>
36	  </form>
37	  <div class="filters" role="group" aria-label="Filter todos">
38	    <button data-testid="filter-all" type="button" data-filter="all" aria-pressed="true">All</button>
39	    <button data-testid="filter-active" type="button" data-filter="active" aria-pressed="false">Active</button>
40	    <button data-testid="filter-completed" type="button" data-filter="completed" aria-pressed="false">Completed</button>
41	  </div>
42	  <ul data-testid="todo-list"></ul>
43	</main>
44	<script>
45	  var STORAGE_KEY = 'todos';
46	  var form = document.getElementById('todo-form');
47	  var input = document.querySelector('[data-testid="todo-input"]');
48	  var dueInput = document.querySelector('[data-testid="todo-due"]');
49	  var list = document.querySelector('[data-testid="todo-list"]');
50	  var filterButtons = document.querySelectorAll('[data-filter]');
51	  var currentFilter = 'all';
52	
53	  // [REQ-001] Load todos from localStorage; ignore malformed data.
54	  function loadTodos() {
55	    try {
56	      var parsed = JSON.parse(localStorage.getItem(STORAGE_KEY));
57	      if (!Array.isArray(parsed)) return [];
58	      // [REQ-002] Todos saved before completion existed default to active.
59	      parsed.forEach(function (t) {
60	        t.completed = t.completed === true;
61	        // [REQ-003] Drop anything that is not a plain YYYY-MM-DD string.
62	        t.due = normalizeDue(t.due);
63	      });
64	      return parsed;
65	    } catch (e) {
66	      return [];
67	    }
68	  }
69	
70	  // [REQ-001]
71	  function saveTodos() {
72	    try { localStorage.setItem(STORAGE_KEY, JSON.stringify(todos)); } catch (e) {}
73	  }
74	
75	  // [REQ-001] Stable unique id; crypto.randomUUID is not available in every file:// context.
76	  function makeId() {
77	    if (window.crypto && typeof crypto.randomUUID === 'function') {
78	      try { return crypto.randomUUID(); } catch (e) {}
79	    }
80	    return Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10);
81	  }
82	
83	  // [REQ-003] Due dates are plain YYYY-MM-DD strings, treated as local calendar dates. Never parsed through UTC.
84	  function normalizeDue(value) {
85	    return typeof value === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(value) ? value : null;
86	  }
87	
88	  // [REQ-003] Today's local calendar date as YYYY-MM-DD.
89	  function localToday(now) {
90	    function pad(n) { return (n < 10 ? '0' : '') + n; }
91	    return now.getFullYear() + '-' + pad(now.getMonth() + 1) + '-' + pad(now.getDate());
92	  }
93	
94	  // [REQ-003] Overdue means strictly before today's local date. Same-format strings compare correctly as text.
95	  function isOverdue(due, today) {
96	    return due !== null && due < today;
97	  }
98	
99	  // [REQ-002] Ordering decision: active todos first, completed below; insertion order within each group.
100	  // The todos array is kept in insertion order, so a stable split preserves it.
101	  function orderTodos(items) {
102	    return items.filter(function (t) { return !t.completed; })
103	      .concat(items.filter(function (t) { return t.completed; }));
104	  }
105	
106	  // [REQ-002]
107	  function matchesFilter(todo, filter) {
108	    if (filter === 'active') return !todo.completed;
109	    if (filter === 'completed') return todo.completed;
110	    return true;
111	  }
112	
113	  // [REQ-001] [REQ-002] [REQ-003]
114	  function render() {
115	    list.textContent = '';
116	    var today = localToday(new Date());
117	    filterButtons.forEach(function (btn) {
118	      btn.setAttribute('aria-pressed', String(btn.dataset.filter === currentFilter));
119	    });
120	    orderTodos(todos).filter(function (t) { return matchesFilter(t, currentFilter); }).forEach(function (todo) {
121	      var li = document.createElement('li');
122	      li.setAttribute('data-testid', 'todo-item');
123	      li.setAttribute('data-completed', String(todo.completed));
124	      li.setAttribute('data-overdue', String(isOverdue(todo.due, today)));
125	      li.dataset.id = todo.id;
126	
127	      var toggle = document.createElement('input');
128	      toggle.type = 'checkbox';
129	      toggle.setAttribute('data-testid', 'todo-toggle');
130	      toggle.checked = todo.completed;
131	      toggle.setAttribute('aria-label', 'Mark "' + todo.text + '" ' + (todo.completed ? 'incomplete' : 'complete'));
132	      toggle.addEventListener('change', function () { toggleTodo(todo.id); });
133	
134	      var text = document.createElement('span');
135	      text.setAttribute('data-testid', 'todo-text');
136	      text.textContent = todo.text;
137	
138	      var del = document.createElement('button');
139	      del.type = 'button';
140	      del.setAttribute('data-testid', 'todo-delete');
141	      del.textContent = 'Delete';
142	      del.setAttribute('aria-label', 'Delete "' + todo.text + '"');
143	      del.addEventListener('click', function () { deleteTodo(todo.id); });
144	
145	      li.appendChild(toggle);
146	      li.appendChild(text);
147	      if (todo.due) {
148	        var due = document.createElement('span');
149	        due.className = 'due';
150	        due.setAttribute('data-testid', 'todo-due-date');
151	        due.textContent = 'Due ' + todo.due;
152	        li.appendChild(due);
153	      }
154	      li.appendChild(del);
155	      list.appendChild(li);
156	    });
157	  }
158	
159	  // [REQ-001] [REQ-003]
160	  function addTodo(rawText, rawDue) {
161	    var text = rawText.trim();
162	    if (!text) return;
163	    todos.push({ id: makeId(), text: text, createdAt: Date.now(), completed: false, due: normalizeDue(rawDue) });
164	    saveTodos();
165	    render();
166	  }
167	
168	  // [REQ-001]
169	  function deleteTodo(id) {
170	    todos = todos.filter(function (t) { return t.id !== id; });
171	    saveTodos();
172	    render();
173	  }
174	
175	  // [REQ-002] Flip completion in place; the array keeps insertion order.
176	  function toggleTodo(id) {
177	    todos.forEach(function (t) { if (t.id === id) t.completed = !t.completed; });
178	    saveTodos();
179	    render();
180	  }
181	
182	  var todos = loadTodos();
183	
184	  filterButtons.forEach(function (btn) {
185	    btn.addEventListener('click', function () {
186	      currentFilter = btn.dataset.filter;
187	      render();
188	    });
189	  });
190	
191	  form.addEventListener('submit', function (e) {
192	    e.preventDefault();
193	    addTodo(input.value, dueInput.value);
194	    input.value = '';
195	    dueInput.value = '';
196	    input.focus();
197	  });
198	
199	  // [REQ-003] Recompute overdue state when the page regains focus, in case the local date has changed.
200	  window.addEventListener('focus', render);
201	
202	  render();
203	</script>
204	</body>
205	</html>
